<?php
require_once '../includes/auth.php'; require_once '../config/database.php'; require_once '../includes/helpers.php';
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT); $statement = $pdo->prepare('SELECT * FROM bills WHERE id = ?'); $statement->execute([$id]); $bill = $statement->fetch(); if (!$bill) { http_response_code(404); exit('Bill not found.'); }
$itemStatement = $pdo->prepare('SELECT * FROM bill_items WHERE bill_id = ? ORDER BY id'); $itemStatement->execute([$id]); $items = $itemStatement->fetchAll(); $address = implode(', ', array_filter([$bill['address'], $bill['village'], $bill['post_office'], $bill['police_station'], $bill['district'], $bill['block'], $bill['gp_municipality']])); $pageTitle = 'Bill ' . $bill['bill_number']; require_once '../includes/header.php';
?>
<section class="card"><div class="title-row"><div><h1>Bill <?= e($bill['bill_number']) ?></h1><p>Invoice <?= e($bill['invoice_no']) ?> | <?= e(displayDate($bill['bill_date'])) ?> <?= e($bill['bill_time']) ?></p></div><a class="button" target="_blank" href="print.php?id=<?= $bill['id'] ?>">Print</a></div><div class="details"><p><b>Patient registration no.:</b> <?= e($bill['patient_registration_no']) ?></p><p><b>Patient:</b> <?= e($bill['patient_name']) ?><?= $bill['age'] ? ', ' . e($bill['age']) : '' ?><?= $bill['gender'] ? ', ' . e($bill['gender']) : '' ?></p><p><b>Mobile:</b> <?= e($bill['mobile']) ?></p><p><b>Address:</b> <?= e($address) ?><?= $bill['pin'] ? ' - ' . e($bill['pin']) : '' ?></p><p><b>Diagnosis:</b> <?= nl2br(e($bill['diagnosis_summary'])) ?></p></div><table><thead><tr><th>Type</th><th>Particular</th><th>Rate</th><th>Qty</th><th>Amount</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?= e($item['item_type']) ?></td><td><?= e($item['particular']) ?></td><td><?= number_format((float) $item['rate'], 2) ?></td><td><?= e($item['quantity']) ?></td><td><?= number_format((float) $item['amount'], 2) ?></td></tr><?php endforeach; ?></tbody></table><div class="amount-summary"><p>Gross: <?= number_format((float) $bill['gross_amount'], 2) ?></p><p>Discount: <?= number_format((float) $bill['discount_amount'], 2) ?></p><p><b>Net: <?= number_format((float) $bill['net_amount'], 2) ?></b></p><p>Paid: <?= number_format((float) $bill['paid_amount'], 2) ?></p><p>Due: <?= number_format((float) $bill['balance_amount'], 2) ?></p></div></section><?php require_once '../includes/footer.php'; ?>